const payload = $input.first().json || {};
return {
  brand_id: payload.brand_id || null,
  triggered_by: payload.triggered_by || 'schedule',
  checked_at: new Date().toISOString()
};

const brands = $input.all().map(b => b.json);
const at_risk = brands.filter(b => b.cost_status !== 'normal');
const now = new Date();
console.log(`[S02] checked ${brands.length} brands, ${at_risk.length} at risk`);
if (at_risk.length === 0) {
  return [{ at_risk_count: 0, action: 'none', triggered_by: $('Parse Trigger').first().json.triggered_by, checked_at: now.toISOString() }];
}
// Dedup: skip brands already alerted within cooldown window.
// Breached = 1h cooldown (urgent), approaching = 24h cooldown.
const COOLDOWN_BREACHED_MS  = 60 * 60 * 1000;       // 1 hour
const COOLDOWN_APPROACH_MS  = 24 * 60 * 60 * 1000;  // 24 hours
const needs_alert = at_risk.filter(b => {
  if (!b.last_alert_sent_at) return true;
  const lastSent = new Date(b.last_alert_sent_at).getTime();
  const elapsed  = now.getTime() - lastSent;
  const cooldown = (b.cost_status === 'breached' || b.cost_status === 'critical')
    ? COOLDOWN_BREACHED_MS
    : COOLDOWN_APPROACH_MS;
  return elapsed >= cooldown;
});
console.log(`[S02] ${needs_alert.length}/${at_risk.length} brands need alert after dedup`);
if (needs_alert.length === 0) {
  return [{ at_risk_count: 0, action: 'none', note: 'all_within_cooldown', triggered_by: $('Parse Trigger').first().json.triggered_by, checked_at: now.toISOString() }];
}
return needs_alert.map(b => ({
  brand_id: b.brand_id,
  current_month_spend_usd: b.current_month_spend_usd,
  monthly_ceiling_usd: b.monthly_ceiling_usd,
  spend_pct: b.spend_pct,
  cost_status: b.cost_status,
  action: (b.cost_status === 'breached' || b.cost_status === 'critical') ? 'halt_generation' : 'alert_management',
  triggered_by: $('Parse Trigger').first().json.triggered_by,
  checked_at: now.toISOString()
}));

const b = $json;
const isBreached = b.cost_status === 'breached' || b.cost_status === 'critical';
const anomaly_type = isBreached ? 'cost_ceiling_breached' : 'cost_ceiling_approaching';
const severity = b.cost_status === 'breached' ? 'critical'
  : b.cost_status === 'critical' ? 'error'
  : 'warning';
return {
  brand_id: b.brand_id,
  flow_id: 'N8N-S02',
  anomaly_type,
  severity,
  details: {
    cost_status: b.cost_status,
    current_spend_usd: b.current_month_spend_usd,
    ceiling_usd: b.monthly_ceiling_usd,
    spend_pct: b.spend_pct,
    action: b.action
  },
  source_flow: 'N8N-S02',
  resolved: false,
  triggered_by: b.triggered_by,
  created_at: b.checked_at
};

// Stamp last_alert_sent_at on brand_cost_config so next S02 run
// can skip this brand within the cooldown window.
const SUPABASE_URL         = 'https://redzmrlzhxkkpgcokgvl.supabase.co';
const SUPABASE_SERVICE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const b = $('Prepare Anomaly').first().json;
if (!b.brand_id) return { stamped: false };
try {
  await $helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/brand_cost_config?brand_id=eq.${b.brand_id}`,
    headers: {
      apikey: SUPABASE_SERVICE_KEY,
      Authorization: `Bearer ${SUPABASE_SERVICE_KEY}`,
      'Content-Type': 'application/json',
      Prefer: 'return=minimal',
    },
    body: JSON.stringify({
      last_alert_sent_at: new Date().toISOString(),
      last_alert_type: b.anomaly_type,
    }),
    json: false,
  });
  console.log(`[S02] stamped last_alert_sent_at for brand ${b.brand_id}`);
} catch (e) {
  console.error('[S02] stamp failed:', e.message);
}
return { stamped: true, brand_id: b.brand_id, anomaly_type: b.anomaly_type };
